import com.nova.godzillagotchi.*;import android.content.SharedPreferences;import java.util.*;import java.lang.reflect.*;
public class CareStoreTest {
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 static SharedPreferences prefs(final Map<String,Object> values){return (SharedPreferences)Proxy.newProxyInstance(CareStoreTest.class.getClassLoader(),new Class[]{SharedPreferences.class},new InvocationHandler(){public Object invoke(Object p,Method m,Object[] a){String n=m.getName();if(n.equals("edit"))return editor(values);if(n.equals("contains"))return values.containsKey(a[0]);if(n.startsWith("get"))return values.containsKey(a[0])?values.get(a[0]):a[1];return null;}});}
 static SharedPreferences.Editor editor(final Map<String,Object> values){return (SharedPreferences.Editor)Proxy.newProxyInstance(CareStoreTest.class.getClassLoader(),new Class[]{SharedPreferences.Editor.class},new InvocationHandler(){public Object invoke(Object p,Method m,Object[] a){if(m.getName().equals("clear"))values.clear();if(m.getName().startsWith("put"))values.put((String)a[0],a[1]);return p;}});}
 public static void main(String[] args){Map<String,Object> v=new HashMap<>();Pet p=new Pet(100);CareStore.load(p,prefs(v),100);check(!p.hatched&&!p.adopted,"new install starts egg");p.eggTaps=3;CareStore.save(p,editor(v));Pet q=new Pet(200);CareStore.load(q,prefs(v),200);check(!q.hatched&&q.eggTaps==3,"egg progress saved");v.clear();v.put("updated",50L);p=new Pet(50);p.xp=1900;p.food=45;CareStore.load(p,prefs(v),100);check(p.hatched&&p.adopted&&p.xp==1900&&p.food==45,"legacy pet preserved");p.name="Nova Jr";p.bonds=9;p.sick=true;p.lightsOff=true;p.messes=2;p.lastGame=75;p.sleepHours=13;CareStore.save(p,editor(v));q=new Pet(200);CareStore.load(q,prefs(v),200);check(q.name.equals("Nova Jr")&&q.bonds==9&&q.sick&&q.lightsOff&&q.messes==2&&q.lastGame==75&&q.sleepHours==13&&q.birthday==100,"care state round trip");v.put("reminders",true);v.put("quiet_start",22);v.put("quiet_end",7);v.put("battle_active",true);v.put("city_active",true);v.put("vehicle_type0",2);v.put("last_reminder",999L);Pet egg=CareStore.newEgg(500);SharedPreferences.Editor reset=CareStore.resetEditor(prefs(v));CareStore.save(egg,reset);v.put("updated",500L);Pet restored=new Pet(500);CareStore.load(restored,prefs(v),600);check(!restored.hatched&&!restored.adopted&&restored.eggTaps==0&&restored.name.equals("Godzilla")&&restored.bonds==0&&!restored.sick&&restored.messes==0,"replacement persists as fresh egg");check(egg.xp==0&&egg.food==80&&egg.energy==85&&egg.lastGame<0,"fresh progress and cooldowns");check(v.get("reminders").equals(true)&&v.get("quiet_start").equals(22)&&v.get("quiet_end").equals(7),"retain reminder preferences");check(!v.containsKey("battle_active")&&!v.containsKey("city_active")&&!v.containsKey("vehicle_type0")&&!v.containsKey("last_reminder"),"remove old encounters and reminder timestamp");System.out.println("PASS: replacement reset and preserved settings; new install, egg resume, legacy migration, care save/load round trip");}
}
